#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int key;
    struct Node *left;
    struct Node *right;
} Node;

static Node *insert(Node *t, int key) {
    if (t == NULL) {
        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            exit(1);
        }
        node->key = key;
        node->left = node->right = NULL;
        return node;
    }
    if (key < t->key) {
        t->left = insert(t->left, key);
    } else if (key > t->key) {
        t->right = insert(t->right, key);
    }
    return t;
}

static void destroy(Node *t) {
    if (t == NULL) {
        return;
    }
    destroy(t->left);
    destroy(t->right);
    free(t);
}

static bool contains(const Node *t, int key) {
    while (t != NULL) {
        if (key == t->key) {
            return true;
        }
        t = key < t->key ? t->left : t->right;
    }
    return false;
}

static int printed;

static void inorder(const Node *t) {
    if (t == NULL) {
        return;
    }
    inorder(t->left);
    printf(printed++ ? " %d" : "%d", t->key);
    inorder(t->right);
}

int main(void) {
    Node *root = NULL;
    char command[8];
    int x;
    while (scanf("%7s %d", command, &x) == 2) {
        if (strcmp(command, "insert") == 0) {
            root = insert(root, x);
        } else if (strcmp(command, "find") == 0) {
            printf("%s\n", contains(root, x) ? "да" : "нет");
        }
    }
    inorder(root);
    printf(printed ? "\n" : "пусто\n");
    destroy(root);
    return 0;
}

