}

static void destroy(Node *t) {
    if (t == NULL) {
        return;
    }
    destroy(t->left);
    destroy(t->right);
    free(t);
}

static bool floor_key(const Node *t, int x, int *out) {
    bool found = false;
    while (t != NULL) {
        if (t->key <= x) {
            *out = t->key;
            found = true;
            t = t->right;
        } else {
            t = t->left;
        }
    }
    return found;
}

static bool ceil_key(const Node *t, int x, int *out) {
    bool found = false;
    while (t != NULL) {
        if (t->key >= x) {
            *out = t->key;
            found = true;
            t = t->left;
        } else {
            t = t->right;
        }
    }
    return found;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) {
        return 0;
    }
    Node *root = NULL;
    for (int i = 0; i < n; i++) {
        int key;
        if (scanf("%d", &key) != 1) {
            break;
        }
        root = insert(root, key);
    }
    int x;
    while (scanf("%d", &x) == 1) {
        int f, c;
        if (floor_key(root, x, &f)) {
            printf("%d ", f);
        } else {
            printf("- ");
        }
        if (ceil_key(root, x, &c)) {
            printf("%d\n", c);
        } else {
            printf("-\n");
        }
    }
    destroy(root);
    return 0;
}

